class PanelQuad
{
public:
	void TurnOn(bool on);
};

class BeachFrontEnd
{
private:
	enum
	{
		MAX_BEACHES_PER_LOC = 3,
		MAX_GOALS_PER_LEVEL = 5
	};

	PanelQuad* completed_lights[MAX_BEACHES_PER_LOC][MAX_GOALS_PER_LEVEL][2];
	PanelQuad* bkg;
	PanelQuad* cell_phone;
	PanelQuad* bio_book;
	PanelQuad* bio_circle;
	PanelQuad* bio_scr[3];
	PanelQuad* bio_scr_marker;
	bool in_frontend;

	void TurnBox(int b_num, bool all_off, float offset);
	void ReadjustBeachPoints();

public:
	void PrepareForLoading();
};

void BeachFrontEnd::PrepareForLoading()
{
	bkg->TurnOn(true);
	in_frontend = false;
	cell_phone->TurnOn(false);
	bio_book->TurnOn(false);
	bio_circle->TurnOn(false);
	for(int i=0; i<3; i++)
		bio_scr[i]->TurnOn(false);
	bio_scr_marker->TurnOn(false);

	TurnBox(0, true, 0);
	ReadjustBeachPoints();

	for(int i=0; i<MAX_BEACHES_PER_LOC; i++)
		for(int j=0; j<MAX_GOALS_PER_LEVEL; j++)
		{
			completed_lights[i][j][0]->TurnOn(false);
			completed_lights[i][j][1]->TurnOn(false);
		}
}
